mapper.select:
SELECT p.product_id AS productId, p.product_name AS title, p.price AS price, p.main_image_url AS thumbnailUrl, p.region_display_name AS regionName, DATE_FORMAT(p.created_at, '%Y-%m-%d %H:%i') AS createdTime,
/* ❤️ 찜 개수 */ ( SELECT COUNT(*) FROM user_favorites uf WHERE uf.product_id = p.product_id ) AS likeCount,
/* ❤️ 내가 찜했는지 (임시 user_id = 1) */ EXISTS ( SELECT 1 FROM user_favorites uf WHERE uf.product_id = p.product_id AND uf.user_id = #{userId} ) AS liked FROM products p WHERE p.sales_status = 'ON_SALE' ORDER BY p.created_at DESC LIMIT 12

SELECT p.product_id AS productId, p.product_name AS title, p.price AS price, p.main_image_url AS thumbnailUrl, p.region_display_name AS regionName, DATE_FORMAT(p.created_at, '%Y-%m-%d %H:%i') AS createdTime,
/* 👁 조회수 */ p.view_count AS viewCount,
/* ❤️ 찜 개수 */ ( SELECT COUNT(*) FROM user_favorites uf WHERE uf.product_id = p.product_id ) AS likeCount,
/* ❤️ 내가 찜했는지 (임시 user_id = 1) */ EXISTS ( SELECT 1 FROM user_favorites uf WHERE uf.product_id = p.product_id AND uf.user_id = #{userId} ) AS liked
FROM products p WHERE p.sales_status = 'ON_SALE'
ORDER BY p.view_count DESC, likeCount DESC, p.created_at DESC
LIMIT 12
